/**
 * Generate canned default tool snapshots from the current database state.
 *
 * Usage:
 *   npx tsx scripts/generate-snapshots.ts
 *   npx tsx scripts/generate-snapshots.ts --page compare-letfs
 *   npx tsx scripts/generate-snapshots.ts --page all
 *   npm run snapshots:generate
 *
 * Notes:
 *   - Uses the latest shared trade date already present in the local DB.
 *   - Reads CPI data from data/inflation.csv (generated by fetch-data).
 *   - Writes per-page JSON files to src/lib/tool-snapshots/.
 */

