const OUTPUT_DIR = join(process.cwd(), "src", "lib", "tool-snapshots");
const MAX_SNAPSHOT_SIZE_BYTES = 5 * 1024 * 1024;
const FUTURES_SNAPSHOT_TARGET_POINTS = 1000;
const DATA_LATEST_END = "9999-12-31";

const PAGE_KEYS = [
  "compare-letfs",
  "compare-sma",
  "compare-threshold",
  "compare-riskoff-assets",
  "statistical-analysis",
  "backtesting",
  "futures",
] as const;

type PageKey = (typeof PAGE_KEYS)[number];

type StrategyResult = {
  label: string;
  runs: RollingSimulationPoint[];
};

type DistributionCategoryWinRates = {
  vsSma: number;
  vsNonSma: number;
  vsUnleveraged: number;
  vsSgov: number;
};

type DistributionSnapshot = {
  chart: {
    x: number[];
    series: Array<{
      key: string;
      label: string;
      color: string;
      borderWidth: number;
      y: number[];
    }>;
  };
  rows: Array<{
    label: string;
    p10: number;
    p50: number;
    avg: number;
    p90: number;
    categoryWinRates: DistributionCategoryWinRates;
  }>;
};

type YearlyGrowthSeries = {
  years: string[];
  series: Array<{ label: string; values: Array<number | null> }>;
  inflation?: Array<number | null>;
};

const DISTRIBUTION_LABEL_ORDER = [
  "TQQQ SMA Next Open",
  "TQQQ",
  LABEL_INDEX_NASDAQ100_TR,
  "UPRO SMA Next Open",
  "UPRO",
  LABEL_INDEX_SP500_TR,
] as const;

