async function buildCompareRiskOffAssetsSnapshot(shared: SharedInputs) {
  const comboSubs = getComboSubPresets(shared.preset);
  const expandedStartDate = getSmaWarmupStartDate(
    shared.startDate,
    Math.max(shared.smaSpPeriod, shared.smaNqPeriod)
  );
  const inflationData = await fetchInflationData(shared.startDate, shared.endDate);
  const [rates, sp500Prices, nasdaqPrices] = await Promise.all([
    loadRates(expandedStartDate, shared.endDate),
    loadPrices("sp500", expandedStartDate, shared.endDate),
    loadPrices("nasdaq100", expandedStartDate, shared.endDate),
  ]);
  const allPrimitiveAssets = getUniquePrimitiveRiskOffAssets(
    RISK_OFF_ASSET_OPTIONS.map((opt) => opt.value as RiskOffAsset)
  );
  const [riskOffSp500, riskOffNasdaq] = await Promise.all([
    loadRiskOffValuesForReference(allPrimitiveAssets, sp500Prices, expandedStartDate, shared.endDate),
    loadRiskOffValuesForReference(allPrimitiveAssets, nasdaqPrices, expandedStartDate, shared.endDate),
  ]);

  const results = await Promise.all(
    comboSubs.map(async (preset) => {
      const prices = preset.index === "nasdaq100" ? nasdaqPrices : sp500Prices;
      const riskOffSeries = preset.index === "nasdaq100" ? riskOffNasdaq : riskOffSp500;
      // Build all risk-off configs + baseline, precompute once, then slice
      const allConfigs: EtfConfig[] = RISK_OFF_ASSET_OPTIONS.map((opt) => {
        const asset = opt.value as RiskOffAsset;
        return createPresetEtfConfig(`riskoff-${asset}`, preset, {
          name: `${preset.leverage}x SMA ${preset.index === "nasdaq100" ? shared.smaNqPeriod : shared.smaSpPeriod} (${asset})`,
          smaEnabled: true,
          smaPeriod: preset.index === "nasdaq100" ? shared.smaNqPeriod : shared.smaSpPeriod,
          smaUpperBuffer: preset.index === "nasdaq100" ? shared.smaNqUpperBuffer : shared.smaSpUpperBuffer, smaLowerBuffer: preset.index === "nasdaq100" ? shared.smaNqLowerBuffer : shared.smaSpLowerBuffer,
          riskOffAsset: asset,
          smaExecutionMode: shared.smaExecutionMode,
        });
      });
      const baselineConfig = createPresetEtfConfig("baseline", preset, {
        name: `${preset.leverage}x Baseline`,
        simulated: true,
        smaEnabled: false,
        smaPeriod: preset.index === "nasdaq100" ? shared.smaNqPeriod : shared.smaSpPeriod,
        smaUpperBuffer: 0, smaLowerBuffer: 0,
        riskOffAsset: shared.riskOffAsset,
        smaExecutionMode: shared.smaExecutionMode,
      });
      allConfigs.push(baselineConfig);
      const windows = buildRollingWindows({
        prices,
        windowLength: shared.windowLength,
        startDateConstraint: shared.startDate,
        endDateConstraint: shared.endDate,
      });
      const sweepResults = runPrecomputedSweep({
        prices,
        rates,
        configs: allConfigs,
        windows,
        riskOffValuesByAsset: riskOffSeries.closeValuesByAsset,
        riskOffOpenValuesByAsset: riskOffSeries.openValuesByAsset,
      });
      const rows = RISK_OFF_ASSET_OPTIONS.map((opt) => {
        const asset = opt.value as RiskOffAsset;
        const simulations = sweepResults.get(`riskoff-${asset}`) ?? [];
        return {
          riskOffAsset: asset,
          displayLabel: opt.label,
          summary: summarizeSmaRow(0, simulations, inflationData.monthlyCpi),
        };
      });
      const baselineSims = sweepResults.get("baseline") ?? [];
      return {
        rows,
        baseline: baselineSims.length > 0 ? summarizeSmaRow(0, baselineSims, inflationData.monthlyCpi) : null,
      };
    })
  );

  return {
    preset: shared.preset,
    index: "sp500" as IndexKey,
    startDate: shared.startDate,
    endDate: shared.endDate,
    windowLength: shared.windowLength,
    smaSpPeriod: shared.smaSpPeriod,
    smaNqPeriod: shared.smaNqPeriod,
    smaSpUpperBuffer: shared.smaSpUpperBuffer,
    smaNqUpperBuffer: shared.smaNqUpperBuffer,
    smaExecutionMode: shared.smaExecutionMode,
    showBaseline: true,
    annualizedInflation: inflationData.annualizedInflation,
    monthlyCpi: inflationData.monthlyCpi,
    rows: results[0]?.rows ?? [],
    baseline: results[0]?.baseline ?? null,
    rows2: results[1]?.rows ?? [],
    baseline2: results[1]?.baseline ?? null,
  };
}

async function buildSmaSweepSnapshot(
  shared: SharedInputs,
  params: { minSmaPeriod: number; maxSmaPeriod: number; stepSize: number }
) {
  const comboSubs = getComboSubPresets(shared.preset);
  const expandedStartDate = getSmaWarmupStartDate(shared.startDate, params.maxSmaPeriod);
  const inflationData = await fetchInflationData(shared.startDate, shared.endDate);
  const [rates, sp500Prices, nasdaqPrices] = await Promise.all([
    loadRates(expandedStartDate, shared.endDate),
    loadPrices("sp500", expandedStartDate, shared.endDate),
    loadPrices("nasdaq100", expandedStartDate, shared.endDate),
  ]);
  const [riskOffSp500, riskOffNasdaq] = await Promise.all([
    loadRiskOffValuesForReference(
      getUniquePrimitiveRiskOffAssets([shared.riskOffAsset]),
      sp500Prices,
      expandedStartDate,
      shared.endDate
    ),
    loadRiskOffValuesForReference(
      getUniquePrimitiveRiskOffAssets([shared.riskOffAsset]),
      nasdaqPrices,
      expandedStartDate,
      shared.endDate
    ),
  ]);

  const results = comboSubs.map((preset) => {
    const prices = preset.index === "nasdaq100" ? nasdaqPrices : sp500Prices;
    const riskOffSeries = preset.index === "nasdaq100" ? riskOffNasdaq : riskOffSp500;
    const windows = buildRollingWindows({
      prices,
      windowLength: shared.windowLength,
      startDateConstraint: shared.startDate,
      endDateConstraint: shared.endDate,
    });
    // Build all SMA configs + baseline, precompute once, then slice
    const allConfigs: EtfConfig[] = [];
    for (let sma = params.minSmaPeriod; sma <= params.maxSmaPeriod; sma += params.stepSize) {
      allConfigs.push(createPresetEtfConfig(`sma-${sma}`, preset, {
        name: `${preset.leverage}x SMA ${sma}`,
        smaEnabled: true,
        smaPeriod: sma,
        smaUpperBuffer: preset.index === "nasdaq100" ? shared.smaNqUpperBuffer : shared.smaSpUpperBuffer, smaLowerBuffer: preset.index === "nasdaq100" ? shared.smaNqLowerBuffer : shared.smaSpLowerBuffer,
        riskOffAsset: shared.riskOffAsset,
        smaExecutionMode: shared.smaExecutionMode,
      }));
    }
    const baselineConfig = createPresetEtfConfig("baseline", preset, {
      name: `${preset.leverage}x Baseline`,
      simulated: true,
      smaEnabled: false,
      smaPeriod: getDefaultSmaPeriod(preset.index),
      smaUpperBuffer: 0, smaLowerBuffer: 0,
      riskOffAsset: shared.riskOffAsset,
      smaExecutionMode: shared.smaExecutionMode,
    });
    allConfigs.push(baselineConfig);
    const sweepResults = runPrecomputedSweep({
      prices,
      rates,
      configs: allConfigs,
      windows,
      riskOffValuesByAsset: riskOffSeries.closeValuesByAsset,
      riskOffOpenValuesByAsset: riskOffSeries.openValuesByAsset,
    });
    const rows: SmaComparisonRow[] = [];
    for (let sma = params.minSmaPeriod; sma <= params.maxSmaPeriod; sma += params.stepSize) {
      const simulations = sweepResults.get(`sma-${sma}`) ?? [];
      rows.push(summarizeSmaRow(sma, simulations, inflationData.monthlyCpi));
    }
    const baselineSims = sweepResults.get("baseline") ?? [];
    return {
      rows,
      baseline: baselineSims.length > 0 ? summarizeSmaRow(0, baselineSims, inflationData.monthlyCpi) : null,
    };
  });

  return {
    preset: shared.preset,
    index: "sp500" as IndexKey,
    startDate: shared.startDate,
    endDate: shared.endDate,
    windowLength: shared.windowLength,
    minSmaPeriod: params.minSmaPeriod,
    maxSmaPeriod: params.maxSmaPeriod,
    stepSize: params.stepSize,
    smaSpUpperBuffer: shared.smaSpUpperBuffer,
    smaNqUpperBuffer: shared.smaNqUpperBuffer,
    riskOffAsset: shared.riskOffAsset,
    smaExecutionMode: shared.smaExecutionMode,
    showBaseline: true,
    annualizedInflation: inflationData.annualizedInflation,
    monthlyCpi: inflationData.monthlyCpi,
    rows: results[0]?.rows ?? [],
    baseline: results[0]?.baseline ?? null,
    rows2: results[1]?.rows ?? [],
    baseline2: results[1]?.baseline ?? null,
  };
}

async function buildBufferSweepSnapshot(
  shared: SharedInputs,
  params: {
    minBuffer: number;
    maxBuffer: number;
    fineStep: number;
    coarseStep: number;
    fineHalfWidth: number;
  }
) {
  const comboSubs = getComboSubPresets(shared.preset);
  const expandedStartDate = getSmaWarmupStartDate(
    shared.startDate,
    Math.max(shared.smaSpPeriod, shared.smaNqPeriod)
  );
  const inflationData = await fetchInflationData(shared.startDate, shared.endDate);
  const inflPct = inflationData.monthlyCpi.length >= 2 ? 0 : inflationData.annualizedInflation * 100;
  const [rates, sp500Prices, nasdaqPrices] = await Promise.all([
    loadRates(expandedStartDate, shared.endDate),
    loadPrices("sp500", expandedStartDate, shared.endDate),
    loadPrices("nasdaq100", expandedStartDate, shared.endDate),
  ]);
  const [riskOffSp500, riskOffNasdaq] = await Promise.all([
    loadRiskOffValuesForReference(
      getUniquePrimitiveRiskOffAssets([shared.riskOffAsset]),
      sp500Prices,
      expandedStartDate,
      shared.endDate
    ),
    loadRiskOffValuesForReference(
      getUniquePrimitiveRiskOffAssets([shared.riskOffAsset]),
      nasdaqPrices,
      expandedStartDate,
      shared.endDate
    ),
  ]);

  const coarsePoints = planCoarseGrid({
    minUpper: params.minBuffer,
    maxUpper: params.maxBuffer,
    minLower: params.minBuffer,
    maxLower: params.maxBuffer,
    coarseStep: params.coarseStep,
  });

  const results = comboSubs.map((preset) => {
    const prices = preset.index === "nasdaq100" ? nasdaqPrices : sp500Prices;
    const riskOffSeries = preset.index === "nasdaq100" ? riskOffNasdaq : riskOffSp500;
    const period = preset.index === "nasdaq100" ? shared.smaNqPeriod : shared.smaSpPeriod;
    const windows = buildRollingWindows({
      prices,
      windowLength: shared.windowLength,
      startDateConstraint: shared.startDate,
      endDateConstraint: shared.endDate,
    });

    // Symmetric 1D sweep + baseline + coarse asymmetric grid in one precompute.
    const allConfigs: EtfConfig[] = [];
    for (let buffer = params.minBuffer; buffer <= params.maxBuffer + 1e-9; buffer += params.fineStep) {
      const roundedBuffer = Number(buffer.toFixed(6));
      allConfigs.push(createPresetEtfConfig(`buffer-${roundedBuffer}`, preset, {
        name: `${preset.leverage}x SMA ${roundedBuffer}%`,
        smaEnabled: true,
        smaPeriod: period,
        smaUpperBuffer: roundedBuffer, smaLowerBuffer: roundedBuffer,
        riskOffAsset: shared.riskOffAsset,
        smaExecutionMode: shared.smaExecutionMode,
      }));
    }
    allConfigs.push(createPresetEtfConfig("baseline", preset, {
      name: `${preset.leverage}x Baseline`,
      simulated: true,
      smaEnabled: false,
      smaPeriod: period,
      smaUpperBuffer: 0, smaLowerBuffer: 0,
      riskOffAsset: shared.riskOffAsset,
      smaExecutionMode: shared.smaExecutionMode,
    }));
    for (const { upper, lower } of coarsePoints) {
      allConfigs.push(createPresetEtfConfig(`asym-${upper}-${lower}`, preset, {
        name: `${preset.leverage}x SMA U${upper}/L${lower}`,
        smaEnabled: true,
        smaPeriod: period,
        smaUpperBuffer: upper, smaLowerBuffer: lower,
        riskOffAsset: shared.riskOffAsset,
        smaExecutionMode: shared.smaExecutionMode,
      }));
    }

    const sweepResults = runPrecomputedSweep({
      prices,
      rates,
      configs: allConfigs,
      windows,
      riskOffValuesByAsset: riskOffSeries.closeValuesByAsset,
      riskOffOpenValuesByAsset: riskOffSeries.openValuesByAsset,
    });

    const rows: SmaComparisonRow[] = [];
    for (let buffer = params.minBuffer; buffer <= params.maxBuffer + 1e-9; buffer += params.fineStep) {
      const roundedBuffer = Number(buffer.toFixed(6));
      const simulations = sweepResults.get(`buffer-${roundedBuffer}`) ?? [];
      rows.push(summarizeSmaRow(roundedBuffer, simulations, inflationData.monthlyCpi));
    }
    const baselineSims = sweepResults.get("baseline") ?? [];

    const coarseRows: AsymmetricSweepRow[] = coarsePoints.map(({ upper, lower }) => {
      const simulations = sweepResults.get(`asym-${upper}-${lower}`) ?? [];
      return {
        ...summarizeSmaRow(upper, simulations, inflationData.monthlyCpi),
        upperBuffer: upper,
        lowerBuffer: lower,
        stage: "coarse",
      };
    });

    const topCoarse = pickTopCell(coarseRows, "score", inflPct);
    let asymRows: AsymmetricSweepRow[] = coarseRows;
    let fineWindow: { minU: number; maxU: number; minL: number; maxL: number } | null = null;

    if (topCoarse) {
      fineWindow = {
        minU: Math.max(params.minBuffer, topCoarse.upperBuffer - params.fineHalfWidth),
        maxU: Math.min(params.maxBuffer, topCoarse.upperBuffer + params.fineHalfWidth),
        minL: Math.max(params.minBuffer, topCoarse.lowerBuffer - params.fineHalfWidth),
        maxL: Math.min(params.maxBuffer, topCoarse.lowerBuffer + params.fineHalfWidth),
      };
      const finePoints = dedupePoints(
        planFineGrid({
          centerUpper: topCoarse.upperBuffer,
          centerLower: topCoarse.lowerBuffer,
          halfWidth: params.fineHalfWidth,
          fineStep: params.fineStep,
          bounds: {
            minUpper: params.minBuffer,
            maxUpper: params.maxBuffer,
            minLower: params.minBuffer,
            maxLower: params.maxBuffer,
          },
        }),
        coarsePoints
      );
      if (finePoints.length > 0) {
        const fineConfigs = finePoints.map(({ upper, lower }) =>
          createPresetEtfConfig(`asym-${upper}-${lower}`, preset, {
            name: `${preset.leverage}x SMA U${upper}/L${lower} (fine)`,
            smaEnabled: true,
            smaPeriod: period,
            smaUpperBuffer: upper, smaLowerBuffer: lower,
            riskOffAsset: shared.riskOffAsset,
            smaExecutionMode: shared.smaExecutionMode,
          })
        );
        const fineResults = runPrecomputedSweep({
          prices,
          rates,
          configs: fineConfigs,
          windows,
          riskOffValuesByAsset: riskOffSeries.closeValuesByAsset,
          riskOffOpenValuesByAsset: riskOffSeries.openValuesByAsset,
        });
        const fineRows: AsymmetricSweepRow[] = finePoints.map(({ upper, lower }) => {
          const simulations = fineResults.get(`asym-${upper}-${lower}`) ?? [];
          return {
            ...summarizeSmaRow(upper, simulations, inflationData.monthlyCpi),
            upperBuffer: upper,
            lowerBuffer: lower,
            stage: "fine",
          };
        });
        asymRows = [...coarseRows, ...fineRows];
      }
    }

    return {
      rows,
      baseline: baselineSims.length > 0 ? summarizeSmaRow(0, baselineSims, inflationData.monthlyCpi) : null,
      asymRows,
      fineWindow,
    };
  });

  return {
    preset: shared.preset,
    index: "sp500" as IndexKey,
    startDate: shared.startDate,
    endDate: shared.endDate,
    windowLength: shared.windowLength,
    smaSpPeriod: shared.smaSpPeriod,
    smaNqPeriod: shared.smaNqPeriod,
    minBuffer: params.minBuffer,
    maxBuffer: params.maxBuffer,
    fineStep: params.fineStep,
    coarseStep: params.coarseStep,
    fineHalfWidth: params.fineHalfWidth,
    riskOffAsset: shared.riskOffAsset,
    smaExecutionMode: shared.smaExecutionMode,
    showBaseline: true,
    annualizedInflation: inflationData.annualizedInflation,
    monthlyCpi: inflationData.monthlyCpi,
    rows: results[0]?.rows ?? [],
    baseline: results[0]?.baseline ?? null,
    rows2: results[1]?.rows ?? [],
    baseline2: results[1]?.baseline ?? null,
    asymRows: results[0]?.asymRows ?? [],
    asymRows2: results[1]?.asymRows ?? [],
    asymFineWindow: results[0]?.fineWindow ?? null,
    asymFineWindow2: results[1]?.fineWindow ?? null,
  };
}

/**
 * Simulate a single config over the full date range, then slice rolling windows.
 * This matches the UI path (precompute-then-slice) instead of re-simulating each window.
 */
function runPrecomputedRolling({
  prices,
  rates,
  etfConfig,
  windowLength,
  startDateConstraint,
  endDateConstraint,
  riskOffValuesByAsset,
  riskOffOpenValuesByAsset,
}: {
  prices: PricePoint[];
  rates: RatePoint[];
  etfConfig: EtfConfig;
  windowLength: number;
  startDateConstraint: string;
  endDateConstraint: string;
  riskOffValuesByAsset?: Partial<Record<RiskOffAsset, number[]>>;
  riskOffOpenValuesByAsset?: Partial<Record<RiskOffAsset, number[]>>;
}): RollingSimulationPoint[] {
  const precomputed = precomputeAllConfigDailyValues(
    prices,
    rates,
    [etfConfig],
    riskOffValuesByAsset,
    riskOffOpenValuesByAsset
  );
  const windows = buildRollingWindows({
    prices,
    windowLength,
    startDateConstraint,
    endDateConstraint,
  });
  const buckets = buildSimulationBuckets(precomputed, windows, prices, {
    rates,
    configs: [etfConfig],
    riskOffValuesByAsset,
    riskOffOpenValuesByAsset,
  });
  return buckets[0]?.simulations ?? [];
}

function buildVariantSummary(label: string, runs: RollingSimulationPoint[]): VariantSummary {
  const summary = summarizeParallelResult(runs);
  return {
    label,
    summary,
    unleveraged: buildUnleveragedSummary(summary.nonLeveragedValues),
  };
}

function getDistributionComparisonLabels(label: string): {
  vsSma?: string;
  vsNonSma?: string;
  vsUnleveraged?: string;
} {
  switch (label) {
    case "TQQQ SMA Next Open":
      return { vsNonSma: "TQQQ", vsUnleveraged: LABEL_INDEX_NASDAQ100_TR };
    case "TQQQ":
      return { vsSma: "TQQQ SMA Next Open", vsUnleveraged: LABEL_INDEX_NASDAQ100_TR };
    case LABEL_INDEX_NASDAQ100_TR:
      return { vsSma: "TQQQ SMA Next Open", vsNonSma: "TQQQ" };
    case "UPRO SMA Next Open":
      return { vsNonSma: "UPRO", vsUnleveraged: LABEL_INDEX_SP500_TR };
    case "UPRO":
      return { vsSma: "UPRO SMA Next Open", vsUnleveraged: LABEL_INDEX_SP500_TR };
    case LABEL_INDEX_SP500_TR:
      return { vsSma: "UPRO SMA Next Open", vsNonSma: "UPRO" };
    default:
      return {};
  }
}

function compareValuesWithTie(left: number, right: number): number {
  if (left > right) return 1;
  if (left < right) return 0;
  return 0.5;
}

function getDistributionLabelOrder(label: string): number {
  const idx = DISTRIBUTION_LABEL_ORDER.indexOf(label as (typeof DISTRIBUTION_LABEL_ORDER)[number]);
  return idx === -1 ? Number.MAX_SAFE_INTEGER : idx;
}

function buildCompareLetfsDistributionSnapshot(
  strategyResults: StrategyResult[],
  monthlyCpi: MonthlyCpiPoint[],
  initialInvestment: number,
  sgovPoints: PricePoint[]
): DistributionSnapshot {
  const includedResults = strategyResults.filter((result) => shouldIncludeStrategyChartLabel(result.label));
  const chart = computeSharedHistogramDistribution(
    includedResults
      .map((result, idx) => ({
        key: result.label,
        label: normalizeStrategyLabel(result.label),
        color: CHART_COLORS.etf[idx % CHART_COLORS.etf.length],
        values: result.runs
          .map((run) => run.cagr - annualizedInflationForRange(monthlyCpi, run.startDate, run.endDate) * 100)
          .filter(Number.isFinite),
        borderWidth: 1.2,
      }))
      .filter((series) => series.values.some(Number.isFinite)),
    90
  );

  const byLabel = new Map(
    includedResults.map((result) => [
      normalizeStrategyLabel(result.label),
      new Map(result.runs.map((run) => [`${run.startDate}|${run.endDate}`, run] as const)),
    ])
  );
  const sgovFinalByWindow = buildSgovFinalValuesByWindow(
    includedResults.flatMap((result) => result.runs.map((run) => ({ startDate: run.startDate, endDate: run.endDate }))),
    sgovPoints,
    initialInvestment
  );

  const computeWinRate = (label: string, opponentLabel?: string): number => {
    if (!opponentLabel) return 0;
    const result = byLabel.get(label);
    const opponent = byLabel.get(opponentLabel);
    if (!result || !opponent) return 0;
    let total = 0;
    let wins = 0;
    for (const [key, run] of result.entries()) {
      const opponentRun = opponent.get(key);
      if (!opponentRun) continue;
      wins += compareValuesWithTie(run.finalValue, opponentRun.finalValue);
      total += 1;
    }
    return total === 0 ? 0 : (wins / total) * 100;
  };

  const computeWinRateVsSgov = (label: string): number => {
    const result = byLabel.get(label);
    if (!result) return 0;
    let total = 0;
    let wins = 0;
    for (const [key, run] of result.entries()) {
      const sgovFinal = sgovFinalByWindow.get(key);
      if (sgovFinal == null) continue;
      wins += compareValuesWithTie(run.finalValue, sgovFinal);
      total += 1;
    }
    return total === 0 ? 0 : (wins / total) * 100;
  };

  const rows = chart.series
    .map((series) => {
      const result = includedResults.find((item) => normalizeStrategyLabel(item.label) === series.label);
      if (!result) return null;
      const values = result.runs
        .map((run) => run.cagr - annualizedInflationForRange(monthlyCpi, run.startDate, run.endDate) * 100)
        .filter(Number.isFinite)
        .sort((a, b) => a - b);
      if (values.length === 0) return null;
      const comparisons = getDistributionComparisonLabels(series.label);
      return {
        label: series.label,
        p10: percentile(values, 0.1),
        p50: percentile(values, 0.5),
        avg: values.reduce((sum, value) => sum + value, 0) / values.length,
        p90: percentile(values, 0.9),
        categoryWinRates: {
          vsSma: computeWinRate(series.label, comparisons.vsSma),
          vsNonSma: computeWinRate(series.label, comparisons.vsNonSma),
          vsUnleveraged: computeWinRate(series.label, comparisons.vsUnleveraged),
          vsSgov: computeWinRateVsSgov(series.label),
        },
      };
    })
    .filter((row): row is DistributionSnapshot["rows"][number] => row !== null)
    .sort((a, b) => getDistributionLabelOrder(a.label) - getDistributionLabelOrder(b.label) || a.label.localeCompare(b.label));

  return { chart, rows };
}

function buildUnleveragedSummary(values: number[]): UnleveragedSummary {
  if (values.length === 0) {
    return { avg: 0, median: 0, best: 0, worst: 0 };
  }
  const sorted = [...values].sort((a, b) => a - b);
  return {
    avg: average(values),
    median: percentile(sorted, 0.5),
    best: Math.max(...values),
    worst: Math.min(...values),
  };
}

function computeSharedHistogramDistribution(
  inputSeries: Array<{
    key: string;
    label: string;
    color: string;
    values: number[];
    borderWidth: number;
  }>,
  requestedBins: number
): {
  x: number[];
  series: Array<{
    key: string;
    label: string;
    color: string;
    borderWidth: number;
    y: number[];
  }>;
} {
  const all = inputSeries.flatMap((series) => series.values).filter(Number.isFinite);
  if (all.length === 0) {
    return { x: [], series: [] };
  }

  const minValue = Math.min(...all);
  const maxValue = Math.max(...all);
  if (!Number.isFinite(minValue) || !Number.isFinite(maxValue)) {
    return { x: [], series: [] };
  }

  const bins = Math.max(20, Math.min(140, Math.round(requestedBins)));
  const span = Math.max(1e-9, maxValue - minValue);
  const binWidth = span / bins;
  const x = Array.from({ length: bins }, (_, i) => minValue + (i + 0.5) * binWidth);

  const toIndex = (value: number): number => {
    const normalized = Math.floor((value - minValue) / binWidth);
    return Math.max(0, Math.min(bins - 1, normalized));
  };

  const series = inputSeries.map((input) => {
    const counts = new Array<number>(bins).fill(0);
    let sampleCount = 0;
    for (const value of input.values) {
      if (!Number.isFinite(value)) continue;
      counts[toIndex(value)] += 1;
      sampleCount += 1;
    }
    const denominator = Math.max(1, sampleCount);
    return {
      key: input.key,
      label: input.label,
      color: input.color,
      borderWidth: input.borderWidth,
      y: counts.map((count) => (count / denominator) * 100),
    };
  });

  return { x, series };
}

function percentile(sorted: number[], p: number): number {
  if (sorted.length === 0) return 0;
  const idx = (sorted.length - 1) * p;
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  const t = idx - lo;
  return sorted[lo] * (1 - t) + sorted[hi] * t;
}

function average(values: number[]): number {
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

/**
 * Pick indices to keep when downsampling an array of length `len` to roughly
 * `target` evenly-spaced points. First and last indices are always kept.
 */
function pickKeepIndices(len: number, target: number): number[] {
  if (len <= target) return Array.from({ length: len }, (_, i) => i);
  const stride = (len - 1) / (target - 1);
  const seen = new Set<number>();
  const keep: number[] = [];
  for (let k = 0; k < target; k++) {
    const idx = Math.round(k * stride);
    if (!seen.has(idx)) {
      seen.add(idx);
      keep.push(idx);
    }
  }
  return keep;
}

function downsampleEtfResult(etf: EtfResult, target: number): EtfResult {
  const idx = pickKeepIndices(etf.dates.length, target);
  return {
    ...etf,
    dates: idx.map((i) => etf.dates[i]),
    dailyValues: idx.map((i) => etf.dailyValues[i]),
    smaPrices:
      etf.smaPrices.length === etf.dates.length
        ? idx.map((i) => etf.smaPrices[i])
        : etf.smaPrices,
  };
}

function downsampleBacktestResult(result: BacktestResult, target: number): BacktestResult {
  const idx = pickKeepIndices(result.dates.length, target);
  return {
    dates: idx.map((i) => result.dates[i]),
    nonLeveragedValues: idx.map((i) => result.nonLeveragedValues[i]),
    investedValues: idx.map((i) => result.investedValues[i]),
    etfResults: result.etfResults.map((etf) => downsampleEtfResult(etf, target)),
  };
}

function getFuturesDefaultStartDate(endDate: string): string {
  const end = new Date(`${endDate}T00:00:00Z`);
  if (!Number.isFinite(end.getTime())) return CONSTANT_SP500_SHORTCUT_DATE;
  end.setUTCFullYear(end.getUTCFullYear() - 20);
  const candidate = end.toISOString().slice(0, 10);
  return candidate < CONSTANT_SP500_SHORTCUT_DATE ? CONSTANT_SP500_SHORTCUT_DATE : candidate;
}

main().catch((err) => {
  console.error("[snapshots] Generation failed:", err);
  process.exit(1);
});
